import mongoose from "mongoose";
import { noteError, noteModel, validateSnapshot } from "./models/note.js";

export const seedSnapshot = {
    schemaVersion: 1,
    notes: [{
        id: "00000000-0000-4000-8000-000000000001",
        title: "Fictional observation", body: "A seed note for the local data lab.",
        tags: ["example"], createdAt: "2026-01-01T00:00:00.000Z", updatedAt: "2026-01-01T00:00:00.000Z",
    }],
};

function ordered(rows) {
    return rows.sort((a, b) => a.id < b.id ? -1 : a.id > b.id ? 1 : 0);
}
function uniqueTitle(rows, title, exceptId) {
    if ([...rows.values()].some(row => row.id !== exceptId && row.title === title)) {
        throw noteError(409, "note_conflict");
    }
}

export async function replaceMemoryNote(rows, id, input, now) {
    // TODO: replace one stored record while retaining its identity.
    throw noteError(501, "not_implemented");
}

export function memoryStore(snapshot = seedSnapshot) {
    const rows = new Map(validateSnapshot(snapshot).map(row => [row.id, row]));
    return {
        kind: "memory", ready: () => true, close: async () => {},
        list: async title => structuredClone(ordered([...rows.values()].filter(row => title === undefined || row.title === title))),
        read: async id => structuredClone(rows.get(id) ?? null),
        create: async input => {
            if (rows.size >= 50) throw noteError(409, "note_limit");
            uniqueTitle(rows, input.title);
            const instant = new Date().toISOString();
            const row = { ...structuredClone(input), id: randomUUID(), createdAt: instant, updatedAt: instant };
            rows.set(row.id, row);
            return structuredClone(row);
        },
        update: (id, input) => replaceMemoryNote(rows, id, input, new Date().toISOString()),
        remove: async id => rows.delete(id),
    };
}

export function localMongoUri(value) {
    // Only an explicitly named, isolated loopback learning database is accepted.
    if (!/^mongodb:\/\/127\.0\.0\.1:[1-9][0-9]{0,4}\/wdf2_[a-z0-9_]+$/.test(value ?? "")) {
        throw noteError(400, "isolated_local_database_required");
    }
    const url = new URL(value);
    if (Number(url.port) > 65535) throw noteError(400, "isolated_local_database_required");
    return value;
}

function publicRecord(row) {
    if (!row) return null;
    return { id: row._id, title: row.title, body: row.body, tags: [...row.tags],
        createdAt: row.createdAt.toISOString(), updatedAt: row.updatedAt.toISOString() };
}

export async function mongoStore(uri, snapshot) {
    const initial = snapshot ? validateSnapshot(snapshot) : null;
    const connection = mongoose.createConnection();
    try {
        await connection.openUri(localMongoUri(uri), {
            serverSelectionTimeoutMS: 1200, connectTimeoutMS: 1200,
            socketTimeoutMS: 1500, heartbeatFrequencyMS: 500,
            maxPoolSize: 2, retryWrites: false, retryReads: false,
        });
        const Model = noteModel(connection);
        await Model.init();
        const count = await Model.countDocuments().maxTimeMS(1000);
        if (initial && count !== 0) throw noteError(409, "restore_target_not_empty");
        if (count > 50) throw noteError(409, "note_limit");
        if (count > 0) {
            try {
                const existing = await Model.find().sort({ _id: 1 }).limit(50).maxTimeMS(1000).lean();
                validateSnapshot({ schemaVersion: 1, notes: existing.map(publicRecord) });
            } catch { throw noteError(409, "stored_data_requires_migration"); }
        }
        if (count === 0) {
            const rows = initial ?? validateSnapshot(seedSnapshot);
            if (rows.length) await Model.insertMany(rows.map(({ id, ...rest }) => ({ _id: id, ...rest })));
        }
        return {
            kind: "mongodb", ready: () => connection.readyState === 1,
            close: () => connection.close(),
            list: async title => (await Model.find(title === undefined ? {} : { title }).sort({ _id: 1 }).limit(50).maxTimeMS(1000).lean()).map(publicRecord),
            read: async id => publicRecord(await Model.findById(id).maxTimeMS(1000).lean()),
            create: async input => {
                if (await Model.countDocuments().maxTimeMS(1000) >= 50) throw noteError(409, "note_limit");
                const now = new Date();
                return publicRecord((await Model.create({ ...input, createdAt: now, updatedAt: now })).toObject());
            },
            update: async (id, input) => publicRecord(await Model.findByIdAndUpdate(id,
                { $set: input, $max: { updatedAt: new Date() } },
                { returnDocument: "after", runValidators: true }).maxTimeMS(1000).lean()),
            remove: async id => Boolean(await Model.findByIdAndDelete(id).maxTimeMS(1000)),
        };
    } catch (error) {
        await connection.close().catch(() => {});
        throw error;
    }
}

import { Router } from "express";
import { idPattern, noteError, validateNoteInput } from "../models/note.js";

export function createNotesRouter(store) {
    const router = Router();
    // One owned lab process serializes mutations. This is not a distributed lock.
    let tail = Promise.resolve();
    const mutation = action => {
        const result = tail.then(action);
        tail = result.catch(() => {});
        return result;
    };
    router.get("/snapshot", async (_request, response) => {
        response.json({ schemaVersion: 1, notes: await store.list() });
    });
    router.get("/", async (request, response) => {
        if (Object.keys(request.query).some(key => key !== "title") ||
            (request.query.title !== undefined && (typeof request.query.title !== "string" ||
            request.query.title.length < 1 || request.query.title.length > 120))) {
            throw noteError(400, "invalid_query");
        }
        response.json(await store.list(request.query.title));
    });
    router.post("/", async (request, response) => {
        const input = validateNoteInput(request.body);
        const note = await mutation(() => store.create(input));
        response.status(201).json(note);
    });
    router.param("id", (request, _response, next, id) => {
        if (!idPattern.test(id)) return next(noteError(400, "invalid_id"));
        next();
    });
    router.get("/:id", async (request, response) => {
        const row = await store.read(request.params.id);
        if (!row) throw noteError(404, "note_not_found");
        response.json(row);
    });
    router.put("/:id", async (request, response) => {
        const input = validateNoteInput(request.body);
        const row = await mutation(() => store.update(request.params.id, input));
        if (!row) throw noteError(404, "note_not_found");
        response.json(row);
    });
    router.delete("/:id", async (request, response) => {
        if (!await mutation(() => store.remove(request.params.id))) throw noteError(404, "note_not_found");
        response.status(204).end();
    });
    router.all(["/", "/:id"], (_request, response) => {
        response.set("Allow", "GET, HEAD, POST, PUT, DELETE").status(405).json({ error: "method_not_allowed" });
    });
    return router;
}

import express from "express";
import { fileURLToPath } from "node:url";
import { createNotesRouter } from "./routes/notes.js";

const publicRoot = fileURLToPath(new URL("../public/", import.meta.url));
export function createApp(store, log = () => {}) {
    const app = express();
    app.disable("x-powered-by");
    app.use((_request, response, next) => {
        response.set({ "X-Content-Type-Options": "nosniff", "Cache-Control": "no-store" });
        response.once("finish", () => log({ event: "request", status: response.statusCode }));
        next();
    });
    app.get("/health", (_request, response) => response.json({ ok: true, store: store.kind }));
    app.get("/api/ready", (_request, response) => {
        const ready = store.ready();
        response.status(ready ? 200 : 503).json({ ready });
    });
    app.use("/api/notes", (request, response, next) => {
        if (["POST", "PUT"].includes(request.method) && !request.is("application/json")) {
            return response.status(415).json({ error: "json_required" });
        }
        next();
    }, express.json({ limit: "16kb", strict: false }), createNotesRouter(store));
    for (const [url, file] of [["/", "index.html"], ["/app.js", "app.js"], ["/styles.css", "styles.css"]]) {
        app.get(url, (_request, response) => response.sendFile(file, { root: publicRoot }));
    }
    app.use((request, response) => {
        if (request.path.startsWith("/api/")) return response.status(404).json({ error: "not_found" });
        response.status(404).type("text").send("Not found");
    });
    app.use((error, _request, response, _next) => {
        if (error.type === "entity.too.large") return response.status(413).json({ error: "body_too_large" });
        if (error.type === "entity.parse.failed") return response.status(400).json({ error: "invalid_json" });
        if (error.code === 11000) return response.status(409).json({ error: "note_conflict" });
        const known = ["invalid_note", "not_implemented", "invalid_query", "invalid_id", "note_not_found", "note_limit", "note_conflict"];
        if (known.includes(error.code)) return response.status(error.status).json({ error: error.code });
        response.status(503).json({ error: "storage_unavailable" });
    });
    return app;
}

import { readFile, stat } from "node:fs/promises";
import { createApp } from "./app.js";
import { memoryStore, mongoStore } from "./store.js";

let store, server;
const log = row => console.log(JSON.stringify(row));
async function start() {
    const port = Number(process.env.PORT ?? 3001);
    if (!Number.isInteger(port) || port < 0 || port > 65535) throw new Error("invalid_port");
    const adapter = process.env.NOTES_ADAPTER ?? "memory";
    if (!["memory", "mongodb"].includes(adapter)) throw new Error("invalid_adapter");
    let snapshot;
    if (process.env.NOTES_SEED_FILE) {
        const filename = process.env.NOTES_SEED_FILE;
        try {
            if ((await stat(filename)).size > 1024 * 1024) throw new Error("invalid_snapshot");
            snapshot = JSON.parse(await readFile(filename, "utf8"));
        } catch { throw new Error("invalid_snapshot"); }
    }
    store = adapter === "memory" ? memoryStore(snapshot) : await mongoStore(process.env.MONGODB_URI, snapshot);
    if (process.env.NOTES_SCENARIO === "unavailable") {
        const unavailable = async () => { throw new Error("unavailable"); };
        store = { ...store, ready: () => false, list: unavailable, read: unavailable,
            create: unavailable, update: unavailable, remove: unavailable };
    } else if (process.env.NOTES_SCENARIO && process.env.NOTES_SCENARIO !== "ok") {
        throw new Error("invalid_scenario");
    }
    server = createApp(store, log).listen(port, "127.0.0.1", () => {
        log({ event: "ready", host: "127.0.0.1", port: server.address().port, adapter });
    });
    server.on("error", () => stop(1));
}
let stopping = false;
async function stop(code = 0) {
    if (stopping) return;
    stopping = true;
    const deadline = setTimeout(() => process.exit(1), 3000);
    deadline.unref();
    server?.closeAllConnections();
    if (server?.listening) await new Promise(resolve => server.close(resolve));
    await store?.close().catch(() => {});
    clearTimeout(deadline);
    process.exitCode = code;
}
process.once("SIGTERM", () => stop());
process.once("SIGINT", () => stop());
start().catch(async error => {
    const known = ["invalid_port", "invalid_adapter", "invalid_snapshot", "invalid_scenario",
        "isolated_local_database_required", "restore_target_not_empty", "note_limit", "stored_data_requires_migration"];
    log({ event: "startup_failed", error: known.includes(error.code ?? error.message) ? (error.code ?? error.message) : "storage_unavailable" });
    await stop(1);
});

